package io.github.ningpp.compat;

/** Replacement for System.AggregateException (generated by CSharpToJava converter). */
public class AggregateException extends RuntimeException {
    private int hresult;
    public AggregateException() { super(); }
    public AggregateException(String message) { super(message); }
    public AggregateException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
